-- Entasis Academy, migration 9 : schemas et figures des decks (brouillons).
--
-- Genere par scripts/academy/generer-decks.mjs depuis scripts/academy/decks/*.json :
-- ne pas editer a la main, regenerer. Complete le brouillon courant d un
-- module deja seme par la migration 7 : pose les schemas de la version
-- (remplacement par cle, les autres cles conservees), pose payload.figure
-- sur les exercices existants reperes par (ordre, type) qui n en ont pas
-- encore, insere les exercices nouveaux (ordre au dela du maximum existant)
-- avec leur corrige, ordre et association deja melanges. Idempotent. Une
-- version publiee n est jamais touchee : sans brouillon, raise notice et
-- rien. A appliquer apres la migration 8 (colonne academy_module_versions.schemas).

-- ── Schemas : Allocation et risques (allocation-et-risques) ──
do $schemas_allocation_et_risques$
declare v_mod uuid; v_ver uuid; v_max integer; v_item uuid; v_nouveaux jsonb; v_conserves jsonb;
begin
  select id into v_mod from public.academy_modules where slug = $academy_deck$allocation-et-risques$academy_deck$;
  if v_mod is null then
    raise notice 'academy_9_schemas : module % absent, rien a faire (semer la migration 7 d abord)', $academy_deck$allocation-et-risques$academy_deck$;
    return;
  end if;
  select id into v_ver from public.academy_module_versions where module_id = v_mod and statut = 'brouillon' order by numero desc limit 1;
  if v_ver is null then
    raise notice 'academy_9_schemas : aucun brouillon pour %, rien a faire (une version publiee ne se modifie pas)', $academy_deck$allocation-et-risques$academy_deck$;
    return;
  end if;
  -- Schemas de la version : les cles du deck remplacent les leurs, les autres restent.
  v_nouveaux := $academy_deck$[{"cle":"expositions","titre":"Compter les expositions, pas les lignes","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\"><title>Compter les expositions, pas les lignes</title><rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/><text x=\"320\" y=\"34\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"600\" fill=\"#162443\">Compter les expositions, pas les lignes</text><rect x=\"16\" y=\"54\" width=\"300\" height=\"226\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"166\" y=\"78\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"600\" fill=\"#162443\">Cinq fonds chez trois assureurs</text><rect x=\"26\" y=\"92\" width=\"136\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"94\" y=\"110\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Fonds A, assureur 1</text><rect x=\"26\" y=\"126\" width=\"136\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"94\" y=\"144\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Fonds B, assureur 1</text><rect x=\"26\" y=\"160\" width=\"136\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"94\" y=\"178\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Fonds C, assureur 2</text><rect x=\"26\" y=\"194\" width=\"136\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"94\" y=\"212\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Fonds D, assureur 2</text><rect x=\"26\" y=\"228\" width=\"136\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"94\" y=\"246\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Fonds E, assureur 3</text><line x1=\"162\" y1=\"105\" x2=\"192\" y2=\"175\" stroke=\"#C5A55A\" stroke-width=\"2\"/><line x1=\"162\" y1=\"139\" x2=\"192\" y2=\"175\" stroke=\"#C5A55A\" stroke-width=\"2\"/><line x1=\"162\" y1=\"173\" x2=\"192\" y2=\"175\" stroke=\"#C5A55A\" stroke-width=\"2\"/><line x1=\"162\" y1=\"207\" x2=\"192\" y2=\"175\" stroke=\"#C5A55A\" stroke-width=\"2\"/><line x1=\"162\" y1=\"241\" x2=\"192\" y2=\"175\" stroke=\"#C5A55A\" stroke-width=\"2\"/><rect x=\"192\" y=\"118\" width=\"112\" height=\"114\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"248\" y=\"145\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"600\" fill=\"#162443\">Une seule</text><text x=\"248\" y=\"165\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"600\" fill=\"#162443\">position</text><text x=\"248\" y=\"186\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">grandes valeurs</text><text x=\"248\" y=\"202\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">technologiques</text><text x=\"248\" y=\"218\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">américaines</text><text x=\"166\" y=\"270\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">Cinq lignes, une seule exposition</text><rect x=\"324\" y=\"54\" width=\"300\" height=\"226\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"474\" y=\"78\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"600\" fill=\"#162443\">Le patrimoine d’un dirigeant</text><rect x=\"334\" y=\"92\" width=\"136\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"402\" y=\"110\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Parts de sa société</text><rect x=\"334\" y=\"126\" width=\"136\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"402\" y=\"144\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Murs (société civile)</text><rect x=\"334\" y=\"160\" width=\"136\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"402\" y=\"178\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Résidence principale</text><rect x=\"334\" y=\"194\" width=\"136\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"402\" y=\"212\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Appartement locatif</text><rect x=\"334\" y=\"228\" width=\"136\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\" stroke-dasharray=\"6 4\"/><text x=\"402\" y=\"246\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#162443\">SCPI demandées</text><line x1=\"470\" y1=\"105\" x2=\"500\" y2=\"175\" stroke=\"#C5A55A\" stroke-width=\"2\"/><line x1=\"470\" y1=\"139\" x2=\"500\" y2=\"175\" stroke=\"#C5A55A\" stroke-width=\"2\"/><line x1=\"470\" y1=\"173\" x2=\"500\" y2=\"175\" stroke=\"#C5A55A\" stroke-width=\"2\"/><line x1=\"470\" y1=\"207\" x2=\"500\" y2=\"175\" stroke=\"#C5A55A\" stroke-width=\"2\"/><line x1=\"470\" y1=\"241\" x2=\"500\" y2=\"175\" stroke=\"#C5A55A\" stroke-width=\"2\" stroke-dasharray=\"6 4\"/><rect x=\"500\" y=\"118\" width=\"112\" height=\"114\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"556\" y=\"153\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"600\" fill=\"#162443\">Deux</text><text x=\"556\" y=\"173\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"600\" fill=\"#162443\">expositions</text><text x=\"556\" y=\"194\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">entreprise</text><text x=\"556\" y=\"210\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">et immobilier</text><text x=\"474\" y=\"270\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">Compléter d’abord ce qu’il ne détient pas</text><rect x=\"16\" y=\"292\" width=\"608\" height=\"52\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/><text x=\"320\" y=\"313\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#162443\">Portefeuille global : entreprise, immobilier, épargne salariale, contrats</text><text x=\"320\" y=\"333\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Diversifier dilue le risque propre à chaque actif, pas le risque de marché</text></svg>","legende":"Cinq fonds sur les mêmes valeurs forment une seule position ; une entreprise et trois biens immobiliers, deux expositions seulement. On juge le portefeuille global et on complète d’abord ce qui manque."},{"cle":"lecture_dic","titre":"Lire le DIC : indicateur, période, scénarios","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\"><title>Lire le DIC : indicateur, période, scénarios</title><rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/><text x=\"320\" y=\"34\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"600\" fill=\"#162443\">Lire le DIC : indicateur, période, scénarios</text><circle cx=\"32\" cy=\"72\" r=\"14\" fill=\"#C5A55A\"/><text x=\"32\" y=\"77\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#FFFFFF\">1</text><text x=\"54\" y=\"77\" font-size=\"16\" font-weight=\"600\" fill=\"#162443\">Indicateur de risque</text><text x=\"54\" y=\"97\" font-size=\"13\" fill=\"#2C3548\">Marché et crédit combinés,</text><text x=\"54\" y=\"114\" font-size=\"13\" fill=\"#2C3548\">calculé pour la période recommandée</text><rect x=\"308\" y=\"58\" width=\"40\" height=\"32\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"328\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">1</text><rect x=\"352\" y=\"58\" width=\"40\" height=\"32\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"372\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">2</text><rect x=\"396\" y=\"58\" width=\"40\" height=\"32\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"416\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">3</text><rect x=\"440\" y=\"58\" width=\"40\" height=\"32\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"460\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">4</text><rect x=\"484\" y=\"58\" width=\"40\" height=\"32\" rx=\"8\" fill=\"#C5A55A\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"504\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#FFFFFF\">5</text><rect x=\"528\" y=\"58\" width=\"40\" height=\"32\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"548\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">6</text><rect x=\"572\" y=\"58\" width=\"40\" height=\"32\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"592\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">7</text><text x=\"308\" y=\"110\" font-size=\"13\" fill=\"#8A95A8\">Niveau 1 : pas zéro risque</text><text x=\"612\" y=\"110\" text-anchor=\"end\" font-size=\"13\" fill=\"#8A95A8\">7 : le plus élevé</text><line x1=\"20\" y1=\"126\" x2=\"620\" y2=\"126\" stroke=\"#8A95A8\" stroke-width=\"2\"/><circle cx=\"32\" cy=\"150\" r=\"14\" fill=\"#C5A55A\"/><text x=\"32\" y=\"155\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#FFFFFF\">2</text><text x=\"54\" y=\"155\" font-size=\"16\" font-weight=\"600\" fill=\"#162443\">Période de détention recommandée</text><text x=\"54\" y=\"176\" font-size=\"13\" fill=\"#2C3548\">Le niveau affiché suppose</text><text x=\"54\" y=\"193\" font-size=\"13\" fill=\"#2C3548\">la période recommandée.</text><text x=\"54\" y=\"210\" font-size=\"13\" fill=\"#2C3548\">Ici : 5 sur 7, cinq ans.</text><text x=\"612\" y=\"156\" text-anchor=\"end\" font-size=\"13\" fill=\"#8A95A8\">Période recommandée : 5 ans</text><rect x=\"308\" y=\"166\" width=\"304\" height=\"16\" rx=\"8\" fill=\"#F5EDD8\"/><rect x=\"308\" y=\"166\" width=\"91\" height=\"16\" rx=\"8\" fill=\"#C5A55A\"/><rect x=\"308\" y=\"166\" width=\"304\" height=\"16\" rx=\"8\" fill=\"none\" stroke=\"#162443\" stroke-width=\"2\"/><line x1=\"399\" y1=\"158\" x2=\"399\" y2=\"194\" stroke=\"#C5A55A\" stroke-width=\"2\"/><text x=\"399\" y=\"210\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#162443\">Projet : 18 mois</text><line x1=\"20\" y1=\"226\" x2=\"620\" y2=\"226\" stroke=\"#8A95A8\" stroke-width=\"2\"/><circle cx=\"32\" cy=\"252\" r=\"14\" fill=\"#C5A55A\"/><text x=\"32\" y=\"257\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#FFFFFF\">3</text><text x=\"54\" y=\"257\" font-size=\"16\" font-weight=\"600\" fill=\"#162443\">Scénarios de performance</text><text x=\"54\" y=\"278\" font-size=\"13\" fill=\"#2C3548\">Des estimations, pas un engagement.</text><text x=\"54\" y=\"295\" font-size=\"13\" fill=\"#2C3548\">La tension n’est pas un plancher.</text><rect x=\"308\" y=\"240\" width=\"150\" height=\"28\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"383\" y=\"259\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Défavorable</text><rect x=\"462\" y=\"240\" width=\"150\" height=\"28\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"537\" y=\"259\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Intermédiaire</text><rect x=\"308\" y=\"274\" width=\"150\" height=\"28\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"383\" y=\"293\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Favorable</text><rect x=\"462\" y=\"274\" width=\"150\" height=\"28\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/><text x=\"537\" y=\"293\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\" fill=\"#162443\">Tension</text><rect x=\"16\" y=\"316\" width=\"608\" height=\"32\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/><text x=\"320\" y=\"337\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"600\" fill=\"#162443\">Dater le projet d’abord, puis lire : indicateur, période, scénarios</text></svg>","legende":"On date le projet, puis on lit le DIC dans cet ordre : un indicateur de 1 à 7 calculé pour la période recommandée, cette période comparée à la date du projet, des scénarios qui ne promettent rien."}]$academy_deck$::jsonb;
  select coalesce(jsonb_agg(s), '[]'::jsonb) into v_conserves
    from jsonb_array_elements(coalesce((select schemas from public.academy_module_versions where id = v_ver), '[]'::jsonb)) s
   where not exists (select 1 from jsonb_array_elements(v_nouveaux) x where x ->> 'cle' = s ->> 'cle');
  update public.academy_module_versions set schemas = v_conserves || v_nouveaux, updated_at = now() where id = v_ver;
  -- Figures : posee sur l exercice existant (ordre, type) qui n en a pas ; au dela du maximum, exercice nouveau.
  select coalesce(max(ordre), 0) into v_max from public.academy_items where version_id = v_ver;
  if v_max >= 2 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"expositions"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 2 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 2, $academy_deck$choix$academy_deck$, $academy_deck$Diversification d'ensemble$academy_deck$, 2, $academy_deck${"enonce":"Cas fictif. Un client détient cinq fonds chez trois assureurs. En ouvrant leurs documents, vous voyez qu'ils investissent tous surtout sur les grandes valeurs technologiques américaines. Que concluez-vous ?","choix":["Il est diversifié : cinq fonds et trois établissements","Il est concentré : les cinq lignes forment une seule position","Il est diversifié dès lors que les frais des fonds diffèrent","Il faut comparer les performances de chaque fonds avant de conclure"],"figure":{"ref":"expositions"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":1}$academy_deck$::jsonb, $academy_deck$La diversification se juge sur les expositions réelles, pas sur le nombre de lignes ou d'établissements.$academy_deck$);
  end if;
  if v_max >= 3 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"expositions"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 3 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 3, $academy_deck$choix$academy_deck$, $academy_deck$Diversification d'ensemble$academy_deck$, 3, $academy_deck${"enonce":"Cas fictif. Un dirigeant de transport détient toutes les parts de sa société, ses locaux via une société civile, sa résidence et un appartement locatif. Il veut placer 120 000 euros en SCPI, « c'est de la pierre, je connais ». Que proposez-vous d'abord ?","choix":["Des SCPI, puisqu'il connaît la pierre et le demande","Des classes d'actifs qu'il ne détient pas encore, avant d'envisager la place éventuelle des SCPI","Le fonds en euros seul, pour ne prendre aucun risque","Un fonds de PME de son secteur, qu'il maîtrise"],"figure":{"ref":"expositions"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":1}$academy_deck$::jsonb, $academy_deck$Lu dans l'ensemble, le choix ajoute de l'immobilier à un patrimoine déjà fait d'immobilier et d'une entreprise ; on complète d'abord.$academy_deck$);
  end if;
  if v_max >= 5 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"lecture_dic"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 5 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 5, $academy_deck$choix$academy_deck$, $academy_deck$Horizon du projet$academy_deck$, 2, $academy_deck${"enonce":"Cas fictif. Un fonds affiche un risque de 5 sur 7 et une période de détention recommandée de cinq ans. Le client a besoin de la somme dans dix-huit mois pour un apport immobilier. Que lui dites-vous ?","choix":["5 sur 7 est un niveau intermédiaire, le fonds convient à ce projet","Le niveau affiché suppose cinq ans de détention ; à dix-huit mois, le risque réel est plus élevé et le support ne convient pas","Un fonds noté 4 sur 7 suffirait pour dix-huit mois","La période de détention recommandée n'a pas de portée sur le choix"],"figure":{"ref":"lecture_dic"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":1}$academy_deck$::jsonb, $academy_deck$Le niveau de risque du DIC suppose la détention sur la période recommandée ; plus court, le risque réel est plus élevé.$academy_deck$);
  end if;
  if v_max >= 21 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"lecture_dic"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 21 and type = $academy_deck$multi$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 21, $academy_deck$multi$academy_deck$, $academy_deck$Lecture du DIC$academy_deck$, 2, $academy_deck${"enonce":"Cochez tout ce qu'il faut lire avec le client dans le DIC avant de retenir un support.","choix":["L'indicateur de risque","La période de détention recommandée","Les scénarios défavorable et de tension","Le nom du dépositaire du fonds","La performance du dernier mois"],"figure":{"ref":"lecture_dic"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"indices":[0,1,2]}$academy_deck$::jsonb, $academy_deck$On lit ensemble l'indicateur, la période recommandée comparée à la date du projet, et les scénarios, en précisant qu'ils ne promettent rien.$academy_deck$);
  end if;
  if v_max >= 41 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"expositions"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 41 and type = $academy_deck$trou_choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 41, $academy_deck$trou_choix$academy_deck$, $academy_deck$Diversification d'ensemble$academy_deck$, 1, $academy_deck${"phrase":"Sur le schéma, les cinq fonds de gauche investissent sur les mêmes valeurs : beaucoup de ___, une seule exposition.","choix":["lignes","secteurs","classes d’actifs","scénarios"],"figure":{"ref":"expositions"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Compter les expositions, pas les lignes : cinq fonds investis sur les mêmes grandes valeurs technologiques forment une seule position, quel que soit le nombre d’assureurs.$academy_deck$);
  end if;
  if v_max >= 42 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"expositions"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 42 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 42, $academy_deck$choix$academy_deck$, $academy_deck$Diversification d'ensemble$academy_deck$, 2, $academy_deck${"enonce":"Sur le schéma, la case « SCPI demandées » rejoint en pointillés l’exposition du dirigeant. Que change cet achat à son allocation ?","choix":["Il renforce une exposition qu’il détient déjà","Il diversifie, puisque les SCPI passent par un autre établissement","Il dilue le risque de marché de l’ensemble du patrimoine","Il remplace avantageusement l’appartement locatif"],"figure":{"ref":"expositions"}}$academy_deck$::jsonb)
    returning id into v_item;
